function tradingApp(){return{balance:1000.00,wager:10,winCount:0,loseCount:0,payoutPercent:92,edgePercent:50,outcomeMessage:'⚡ Choose chart mode (Full Refresh / Next Candle) and tap UP/DOWN',outcomeType:'idle',chart:null,candleSeries:null,candlesData:[],chartMode:'fullReset',showTestModal:!1,testStats:{startingBalance:0,finalBalance:0,netPL:0,wins:0,losses:0,observedWinRate:0,totalWagered:0,expectancy:0,edgeUsed:50,balanceHistory:[],winRateHistory:[]},generateRandomCandles(num=55,startPrice=100){let candles=[],prevClose=startPrice;for(let i=0;i<num;i++){let changePct=(Math.random()-0.5)*0.045;let close=+(prevClose*(1+changePct)).toFixed(4);close=Math.max(close,0.5);let open=prevClose;let high=+(Math.max(open,close)*(1+Math.random()*0.015)).toFixed(4);let low=+(Math.min(open,close)*(1-Math.random()*0.012)).toFixed(4);candles.push({time:i,open:+open.toFixed(4),high,low,close:+close.toFixed(4)});prevClose=close}
return candles},updateChartFromData(){if(!this.candleSeries)return;this.candleSeries.setData(this.candlesData);if(this.chart)this.chart.timeScale().fitContent();},refreshFullChart(){this.candlesData=this.generateRandomCandles(55,95+Math.random()*20);this.updateChartFromData()},generateNextCandle(prediction,isWin,prevClose){const targetUp=(prediction==='up'&&isWin)||(prediction==='down'&&!isWin);let open=prevClose;let close;let absMovePercent=0.002+Math.random()*0.038;if(targetUp){close=open*(1+absMovePercent)}else{close=open*(1-absMovePercent)}
close=Math.max(0.25,+close.toFixed(4));let high=+(Math.max(open,close)*(1+Math.random()*0.018)).toFixed(4);let low=+(Math.min(open,close)*(1-Math.random()*0.014)).toFixed(4);high=Math.max(high,open,close);low=Math.min(low,open,close);const newTime=this.candlesData.length;return{time:newTime,open:+open.toFixed(4),high,low,close:+close.toFixed(4)}},setChartMode(mode){this.chartMode=mode;this.outcomeMessage=`🎮 Mode switched to ${mode === 'fullReset' ? 'Full Refresh (new chart each trade)' : 'Next Candle (extend chart + predict)'}`;setTimeout(()=>{if(this.chart)this.chart.timeScale().fitContent();},10)},placeBet(prediction){if(!this.canBet()){this.outcomeMessage='❌ Insufficient balance or invalid wager';this.outcomeType='idle';return}
const wageredAmount=this.wager;const isWin=Math.random()<(this.edgePercent/100);const multiplier=this.payoutPercent/100;let winAmount=0;if(isWin){winAmount=wageredAmount*multiplier;this.balance+=winAmount;this.winCount++}else{this.balance-=wageredAmount;this.loseCount++}
if(this.chartMode==='fullReset'){this.candlesData=this.generateRandomCandles(55,95+Math.random()*20);this.updateChartFromData();if(isWin){this.outcomeMessage=`🎉 WIN +$${winAmount.toFixed(2)} (${this.payoutPercent}% payout) → $${this.balance.toFixed(2)} [Full Refresh Mode]`}else{this.outcomeMessage=`📉 LOSS -$${wageredAmount.toFixed(2)} → $${this.balance.toFixed(2)} [Full Refresh Mode]`}}else if(this.chartMode==='nextCandle'){if(!this.candlesData.length){this.candlesData=this.generateRandomCandles(55,100)}
const prevCandle=this.candlesData[this.candlesData.length-1];const prevClose=prevCandle.close;const newCandle=this.generateNextCandle(prediction,isWin,prevClose);this.candlesData.push(newCandle);this.updateChartFromData();if(isWin){this.outcomeMessage=`🎉 WIN +$${winAmount.toFixed(2)} (${this.payoutPercent}% payout) → $${this.balance.toFixed(2)} | Next candle ${prediction === 'up' ? '📈 BULLISH' : '📉 BEARISH'} (matched your ${prediction} call)`}else{this.outcomeMessage=`📉 LOSS -$${wageredAmount.toFixed(2)} → $${this.balance.toFixed(2)} | Next candle went ${prediction === 'up' ? '🔻 BEARISH' : '📈 BULLISH'} (opposite to your ${prediction} call)`}}
this.outcomeType=isWin?'win':'loss';if(this.wager>this.balance&&this.balance>0)this.wager=Math.max(1,Math.floor(this.balance));if(this.balance<=0)this.outcomeMessage+=' 💀 GAME OVER — press RESET'},canBet(){return this.balance>0&&this.wager>0&&this.wager<=this.balance&&this.chart!==null},adjustWager(delta){let newVal=this.wager+delta;if(newVal<1)newVal=1;if(newVal>this.balance)newVal=this.balance;this.wager=Math.floor(newVal)},syncWagerFromSlider(e){let val=parseFloat(e.target.value);if(isNaN(val))val=1;val=Math.min(this.balance,Math.max(1,val));this.wager=Math.floor(val)},validateWagerFromInput(){let val=parseFloat(this.wager);if(isNaN(val))val=1;val=Math.min(this.balance,Math.max(1,val));this.wager=Math.floor(val)},setWager(amount){this.wager=Math.min(this.balance,Math.max(1,amount))},winRate(){const total=this.winCount+this.loseCount;return total===0?'0%':((this.winCount/total)*100).toFixed(1)+'%'},resetGame(){this.balance=1000;this.winCount=0;this.loseCount=0;this.wager=10;this.payoutPercent=92;this.edgePercent=50;this.candlesData=this.generateRandomCandles(55,100);this.updateChartFromData();this.outcomeMessage='🔄 Game fully reset. Edge = 50%. Mode: '+(this.chartMode==='fullReset'?'Full Refresh':'Next Candle');this.outcomeType='idle';if(this.wager>this.balance)this.wager=this.balance},initChartAndRandomize(){setTimeout(()=>{const container=document.getElementById('trading-chart');if(!container)return;this.chart=LightweightCharts.createChart(container,{layout:{background:{color:'#0a0e17'},textColor:'#d1d5db',fontSize:10},grid:{vertLines:{color:'#1f2a3e'},horzLines:{color:'#1f2a3e'}},crosshair:{mode:LightweightCharts.CrosshairMode.Normal},rightPriceScale:{borderColor:'#2a3a55'},timeScale:{borderColor:'#2a3a55',timeVisible:!0},width:container.clientWidth,height:container.clientHeight,});this.candleSeries=this.chart.addCandlestickSeries({upColor:'#26a69a',downColor:'#ef5350',borderDownColor:'#ef5350',borderUpColor:'#26a69a',wickDownColor:'#ef5350',wickUpColor:'#26a69a',});this.candlesData=this.generateRandomCandles(55,100);this.candleSeries.setData(this.candlesData);this.chart.timeScale().fitContent();window.addEventListener('resize',()=>this.resizeChart());new ResizeObserver(()=>this.resizeChart()).observe(container);this.outcomeMessage='🔥 Ready! Select chart mode and trade.'},30)},resizeChart(){if(this.chart){const container=document.getElementById('trading-chart');if(container){this.chart.applyOptions({width:container.clientWidth,height:container.clientHeight});this.chart.timeScale().fitContent()}}},run300TradeTest(){const startBalance=this.balance;let currentBalance=startBalance;let wins=0,losses=0;const balanceHistory=[startBalance];const winRateHistory=[0];const wagerAmount=this.wager;const payoutMult=this.payoutPercent/100;const winProb=this.edgePercent/100;const totalTrades=300;for(let i=1;i<=totalTrades;i++){const isWinSim=Math.random()<winProb;if(isWinSim){currentBalance+=wagerAmount*payoutMult;wins++}else{currentBalance-=wagerAmount;losses++}
balanceHistory.push(currentBalance);winRateHistory.push((wins/i)*100)}
const finalBalance=currentBalance;const netPL=finalBalance-startBalance;const observedWinRate=(wins/totalTrades)*100;const totalWagered=wagerAmount*totalTrades;const expectancy=netPL/totalTrades;this.testStats={startingBalance:startBalance,finalBalance,netPL,wins,losses,observedWinRate:observedWinRate.toFixed(2),totalWagered,expectancy,edgeUsed:this.edgePercent,balanceHistory,winRateHistory};this.showTestModal=!0;setTimeout(()=>{this.drawEquityCurve();this.drawWinRateCurve()},50)},drawEquityCurve(){const canvas=document.getElementById('equityCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');const w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w;canvas.height=h;const data=this.testStats.balanceHistory;if(!data?.length)return;const minVal=Math.min(...data),maxVal=Math.max(...data),range=maxVal-minVal||1;const stepX=w/(data.length-1);ctx.clearRect(0,0,w,h);ctx.beginPath();ctx.strokeStyle='#38bdf8';ctx.lineWidth=2;for(let i=0;i<data.length;i++){const x=i*stepX,y=h-((data[i]-minVal)/range)*h;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}
ctx.stroke();ctx.fillStyle='#a0aec0';ctx.font='8px monospace';ctx.fillText(`Start: $${this.testStats.startingBalance.toFixed(0)}`,5,15);ctx.fillStyle='#38bdf8';ctx.fillText(`End: $${this.testStats.finalBalance.toFixed(0)}`,w-65,h-5)},drawWinRateCurve(){const canvas=document.getElementById('winrateCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');const w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w;canvas.height=h;const data=this.testStats.winRateHistory;if(!data?.length)return;const stepX=w/(data.length-1);ctx.clearRect(0,0,w,h);ctx.beginPath();ctx.strokeStyle='#f59e0b';ctx.lineWidth=2;for(let i=0;i<data.length;i++){const x=i*stepX,y=h-(data[i]/100)*h;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}
ctx.stroke();ctx.beginPath();ctx.strokeStyle='#4ade80';ctx.lineWidth=1;ctx.setLineDash([5,5]);const yEdge=h-(this.testStats.edgeUsed/100)*h;ctx.moveTo(0,yEdge);ctx.lineTo(w,yEdge);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#a0aec0';ctx.font='8px monospace';ctx.fillText(`Edge ${this.testStats.edgeUsed}%`,w-55,yEdge-2);ctx.fillStyle='#f59e0b';ctx.fillText(`Final: ${this.testStats.observedWinRate}%`,w-65,15)}}}